function openIndicate(){if(!canPost())return;editor={kind:'indicate',photos:[]};editorDirty=false;showDialog('Indicar um negócio',`<div class="form-grid">${field('ind-name','Nome do negócio','','required minlength="3" class="full"')}${selectField('ind-category','Categoria',[['','Escolher categoria'],...CAT_NAMES.slice(1)],'','required')}${selectField('ind-hood','Bairro',[['','Escolher bairro'],...HOODS],'','required')}${field('ind-why','Por que você indica?','','type="textarea" rows="3" required minlength="12" class="full"')}</div><p class="form-note">A página nasce com a sua indicação. O responsável poderá completar as informações depois.</p>`,`${btn('Cancelar','close-dialog','','text')}${btn('Publicar indicação','submit-indicate','','filled','thumb_up')}`,'editor');}
async function submitIndicate(){if(!canPost()||!validFields(['ind-name','ind-category','ind-hood','ind-why']))return;const name=$('#ind-name').value.trim(),cat=$('#ind-category').value,hood=$('#ind-hood').value,why=$('#ind-why').value.trim(),duplicate=cityBiz().find(b=>norm(b.name)===norm(name));const id=duplicate?.id||uid('b');const ok=mutate(()=>{if(duplicate){if(!duplicate.myInd)duplicate.recN++;duplicate.myInd=true;duplicate.says.push([initals(state.profile.name),'me',state.profile.name,why]);}else state.biz.unshift({id,name,city:state.homeCity,cat,hoods:[hood],svc:[],bio:'',hours:'A confirmar com o responsável',photos:[],icon:'storefront',ini:initals(name),claimed:false,myInd:true,recN:1,says:[[initals(state.profile.name),'me',state.profile.name,why]],saved:false});},{redraw:false});if(ok){await closeDialog(true);navigate('negocio',id);notify(duplicate?'Sua indicação foi adicionada':'Negócio indicado');}}
